/**
 * topicAbout — the long-form "About This Topic" overview for each v3 topic,
 * keyed by gs (achievements.global_sequence), exactly as topicCopy.ts is.
 *
 * Authored by Computer B, QA'd by Computer A, delivered 2026-09-19 as
 * `docs/topic_overviews_source_2026-09-19.json`. GENERATED FROM THAT FILE,
 * which was deleted in the same commit — see the note on shipping below.
 * ⛔ Regenerate from a new deliverable; do not hand-edit individual rows.
 *
 * ── WHY A CLIENT FILE AND NOT A DB COLUMN ───────────────────────────────────
 * The 166 keys here are an exact 1:1 with `topicCopy.ts` — verified both ways,
 * none missing on either side. Content that shares a key space, a lifecycle
 * and a review path with an existing client file belongs beside it.
 *
 * The deciding argument is a failure we have already paid for. When the v3
 * certificates/programs tables went public they had an RLS read policy but no
 * table GRANT, and `fetchV3*` swallows errors and returns `[]` — so the
 * catalog came back empty and SILENT. A DB-backed overview would fail exactly
 * that way on 166 screens: the section would simply not appear, with nothing
 * anywhere saying why. This is also static reference text, identical for every
 * user forever, so nothing a database is for actually applies to it.
 *
 * ── ⚠️ THIS FILE IS ~600 KB. IMPORT IT LAZILY. ──────────────────────────────
 * That is more than three times the rest of `src/data` put together, so how it
 * is consumed matters more than usual:
 *
 *   ⛔ NOT  `import { topicAbout } from '../../data/topicAbout';`
 *   ✅ DO   `const { topicAbout } = require('../../data/topicAbout');`
 *           inside the handler that expands the section.
 *
 * A top-level import puts this on the startup path for every screen that
 * transitively reaches it. A require inside the expand handler means the
 * module is not evaluated until someone actually opens "About This Topic".
 * The bytes are in the bundle either way; the startup cost is not.
 *
 * ⚠️ AND WHILE NOTHING IMPORTS IT, IT COSTS NOTHING AT ALL. Metro bundles from
 * the entry point's require graph, so an unreferenced module is not in the
 * bundle. That is why this can land ahead of the UI that will read it: it is
 * inert until the first consumer arrives. Which also means you cannot measure
 * its real bundle cost until then.
 *
 * ── WHY THE SOURCE JSON IS GONE ─────────────────────────────────────────────
 * A JSON file under `docs/` is not in the require graph, so it would not ship
 * — but it would sit in the repo as a second copy of the same content, free to
 * drift from this one and with nothing to say which is authoritative. One copy,
 * and it is this file. The original is in A's delivery folder.
 *
 * ── SHAPE ───────────────────────────────────────────────────────────────────
 * The section keys are the deliverable's own, unchanged. Renaming them to the
 * house camelCase would put a hand-maintained mapping between A's file and
 * this one, which is a thing to get wrong every time the content is reissued.
 * A mechanical transform has no such step.
 */

/** The four sections, always present, always rendered in this order. */
export type TopicAboutSectionKey =
  | 'big_picture'
  | 'in_practice'
  | 'what_youll_develop'
  | 'where_it_connects';

/** Appended after the four, and only where the topic has one. */
export type TopicAboutModuleKey =
  | 'professional_judgment'
  | 'safety_and_responsibility'
  | 'work_environment'
  | 'where_youll_encounter_it'
  | 'who_may_enjoy';

export type TopicAbout = Record<TopicAboutSectionKey, string> & {
  optional_modules?: Partial<Record<TopicAboutModuleKey, string>>;
};

/**
 * Display order for the four required sections. Render by walking this, not by
 * `Object.keys` — key order in an object literal is not a contract.
 */
export const TOPIC_ABOUT_SECTION_ORDER: readonly TopicAboutSectionKey[] = [
  'big_picture',
  'in_practice',
  'what_youll_develop',
  'where_it_connects',
];

export const TOPIC_ABOUT_MODULE_ORDER: readonly TopicAboutModuleKey[] = [
  'professional_judgment',
  'safety_and_responsibility',
  'work_environment',
  'where_youll_encounter_it',
  'who_may_enjoy',
];

